// src/template/template.controller.ts
import { Controller, Post, Body, Get, Query } from '@nestjs/common';
import { TemplateService } from './template.service';

@Controller('template')
export class TemplateController {
  constructor(private readonly templateService: TemplateService) {}

  @Post('render')
  async renderTemplate(@Body() body: { template: string; context: Record<string, any> }) {
    return this.templateService.render(body.template, body.context);
  }

  @Get('preview')
  async previewTemplate(@Query('expr') expr: string) {
    return this.templateService.evaluateExpression(expr);
  }
}

// src/template/template.service.ts
import { Injectable } from '@nestjs/common';
import * as vm from 'vm';
import * as fs from 'fs';
import * as path from 'path';

@Injectable()
export class TemplateService {
  private readonly templateCache = new Map<string, string>();

  render(template: string, context: Record<string, any>): string {
    // Replace ${expression} patterns with evaluated results
    const rendered = template.replace(/\$\{([^}]+)\}/g, (match, expr) => {
      return this.evaluateExpression(expr, context);
    });
    return rendered;
  }

  evaluateExpression(expr: string, context: Record<string, any> = {}): string {
    try {
      // Create a sandbox with the provided context
      const sandbox = {
        ...context,
        Math,
        Date,
        String,
        Number,
        Array,
        Object,
        JSON,
        parseInt,
        parseFloat,
        encodeURIComponent,
        decodeURIComponent,
      };

      // Use vm.runInNewContext for expression evaluation
      // Note: timeout prevents infinite loops
      const result = vm.runInNewContext(expr, sandbox, {
        timeout: 1000,
        displayErrors: false,
      });

      return String(result);
    } catch (error) {
      return `[Error: ${error.message}]`;
    }
  }

  loadTemplate(name: string): string {
    if (this.templateCache.has(name)) {
      return this.templateCache.get(name);
    }
    const filePath = path.join('/app/templates', `${name}.tpl`);
    const content = fs.readFileSync(filePath, 'utf-8');
    this.templateCache.set(name, content);
    return content;
  }
}

